// Grab the raw text output from the previous docker command
const rawOutput = $input.first().json.stdout || '';

// Split the output into individual lines and remove empty rows
const lines = rawOutput.trim().split('\n');

// If there's only a header or nothing at all, stop here
if (lines.length <= 1) {
  return [{ json: { message: "No matching containers found" } }];
}

const containers = [];

// Skip the header row and loop through the data
for (let i = 1; i < lines.length; i++) {
  const line = lines[i].trim();

  // Split by clusters of 2 or more spaces to isolate columns cleanly
  const parts = line.split(/\s{2,}/); 

  if (parts.length >= 3) {
    const rawId = parts[0];
    const name = parts[parts.length - 1]; // Name is typically the last element

    // Find the text block that contains the runtime status info
    const rawStatus = parts.find(p => p.startsWith('Exited') || p.startsWith('Up') || p.startsWith('Created')) || '';

    // Clean up the status down to just the pure exit code number
    let exitCode = "unknown";

    if (rawStatus.startsWith('Up')) {
      exitCode = "0"; // Container is currently running fine
    } else {
      // Look for any numbers trapped inside parentheses, e.g., Exited (143)
      const match = rawStatus.match(/\((\d+)\)/);
      if (match) {
        exitCode = match[1]; // Extract just the digits
      }
    }

    containers.push({
      id: rawId.split(' ')[0], // Grabs only the first word to ensure it's just the ID
      name: name,
      exit_code: exitCode
    });
  }
}

return containers.map(c => ({ json: c }));

